<?php
declare(strict_types=1);
require_once __DIR__ . '/../app/services.php';
$db=db();
$path=trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH) ?: '/','/');
if(str_starts_with($path,'index.php'))$path=trim(substr($path,9),'/');
try{$tenant=current_tenant($db);}catch(Throwable $e){http_response_code(503);echo 'Store setup is required.';exit;}

function h_start(array $tenant,string $title='',string $description='',array $product=[]): void { echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'.seo_head($tenant,$title,$description,$product).'<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Playfair+Display:ital,wght@0,600;1,600&display=swap" rel="stylesheet"><link rel="stylesheet" href="'.asset('tailwind.css').'"><script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script><style>:root{--brand:'.e($tenant['primary_color']).';--soft:'.e($tenant['secondary_color']).';--accent:'.e($tenant['accent_color']).'}body{font-family:DM Sans,sans-serif}.display{font-family:Playfair Display,serif}.theme-glassmorphism .surface{background:rgba(255,255,255,.58);backdrop-filter:blur(16px)}.theme-neomorphism .surface{box-shadow:12px 12px 24px #d7d3cb,-12px -12px 24px #fff}.theme-claymorphism .surface{border-radius:1.5rem;box-shadow:inset 0 2px rgba(255,255,255,.8),0 12px 0 rgba(0,0,0,.08)}.theme-skeuomorphism .surface{box-shadow:inset 0 1px 3px rgba(0,0,0,.25),0 3px 8px rgba(0,0,0,.16)}.theme-brutalism .surface{border:3px solid #171717;border-radius:0;box-shadow:6px 6px #171717}.theme-maximalism{background-image:radial-gradient(circle at 10% 20%,rgba(255,203,116,.18) 0 10%,transparent 10.5%),radial-gradient(circle at 90% 15%,rgba(111,94,242,.13) 0 11%,transparent 11.5%)}.theme-minimal .surface{border-radius:.75rem}</style></head><body class="bg-stone-50 text-zinc-900 theme-'.e($tenant['theme']).'">'.show_flash(); }
function h_end(): void { echo '</body></html>'; }
function categories(PDO $db,int $tenantId): array {$s=$db->prepare('SELECT * FROM categories WHERE tenant_id=? ORDER BY name');$s->execute([$tenantId]);return $s->fetchAll();}
function active_coupons(PDO $db,int $tenantId): array {$s=$db->prepare("SELECT * FROM coupons WHERE tenant_id=? AND is_active=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) ORDER BY id DESC");$s->execute([$tenantId]);return $s->fetchAll();}
function header_nav(PDO $db,array $tenant): void {$coupons=active_coupons($db,$tenant['id']);echo '<div class="bg-zinc-900 text-white text-xs"><div class="mx-auto max-w-7xl px-4 py-2 text-center" x-data="{i:0,n:'.max(1,count($coupons)).'}">';if($coupons){foreach($coupons as $i=>$coupon)echo '<span x-show="i=='.$i.'"><b>'.e($coupon['title']?:'Store offer').'</b> · '.e($coupon['description']?:('Use '.$coupon['code'])).' <button class="ml-2 underline" @click="navigator.clipboard.writeText(\''.e($coupon['code']).'\')">Copy '.e($coupon['code']).'</button></span>';if(count($coupons)>1)echo '<script>setInterval(()=>{let e=document.querySelector("[x-data]");if(e&&e.__x)e.__x.$data.i=(e.__x.$data.i+1)%e.__x.$data.n},4200)</script>';}else echo '<span>Free storefront setup — add offers in the admin workspace.</span>';echo '</div></div><header class="surface sticky top-0 z-30 border-b border-stone-200/70 bg-stone-50/90"><div class="mx-auto flex h-18 max-w-7xl items-center justify-between px-4 py-4" x-data="{open:false}"><a class="flex max-w-[15rem] items-center gap-2 font-bold tracking-tight" href="'.tenant_url($tenant).'">'.($tenant['logo_url']?'<img class="h-8 w-8 object-contain" src="'.e($tenant['logo_url']).'" alt="">':'<span class="grid h-8 w-8 place-items-center rounded-md bg-[var(--brand)] text-white">✦</span>').(($tenant['show_brand_name']||!$tenant['logo_url'])?'<span class="truncate">'.e($tenant['name']).'</span>':'').'</a><button class="md:hidden" @click="open=!open" aria-label="Toggle menu">☰</button><nav class="hidden gap-7 text-sm md:flex"><a href="'.tenant_url($tenant,'shop').'">Shop</a><a href="'.tenant_url($tenant,'about').'">About</a><a href="'.tenant_url($tenant,'search').'">Search</a></nav><div class="hidden items-center gap-4 text-sm md:flex"><a href="'.tenant_url($tenant,'account').'">Account</a><a class="font-semibold" href="'.tenant_url($tenant,'cart').'">Bag ('.cart_count().')</a></div><nav x-show="open" x-transition class="absolute left-0 top-full w-full border-b bg-stone-50 p-4 md:hidden"><a class="block py-2" href="'.tenant_url($tenant,'shop').'">Shop</a><a class="block py-2" href="'.tenant_url($tenant,'about').'">About</a><a class="block py-2" href="'.tenant_url($tenant,'cart').'">Bag ('.cart_count().')</a></nav></div></header>';}
function product_card(array $tenant,array $p): string {$image=product_image($p);return '<article class="group"><a class="surface block aspect-[4/5] overflow-hidden bg-stone-200" href="'.tenant_url($tenant,'product/'.$p['slug']).'">'.($image?'<img class="h-full w-full object-cover transition duration-500 group-hover:scale-105" loading="lazy" src="'.e($image).'" alt="'.e($p['name']).'">':'<span class="grid h-full place-items-center text-sm text-stone-500">Product image</span>').'</a><div class="relative pt-3"><h3 class="text-sm font-semibold"><a href="'.tenant_url($tenant,'product/'.$p['slug']).'">'.e($p['name']).'</a></h3><p class="mt-1 text-xs text-stone-500">'.money((float)$p['price']).'</p><form method="post" action="'.tenant_url($tenant,'cart').'" class="absolute right-0 top-3">'.csrf_input().'<input type="hidden" name="action" value="add_cart"><input type="hidden" name="product_id" value="'.$p['id'].'"><button class="rounded border border-stone-300 bg-white px-2 py-1 text-xs font-semibold">Add +</button></form></div></article>';}
function product_categories(PDO $db,int $productId): array {return array_column(categories_of($db,$productId),'name');}
function cart_products(PDO $db,array $tenant): array {$cart=cart();if(!$cart)return[];$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$db->prepare("SELECT * FROM products WHERE tenant_id=? AND id IN ($marks) AND is_active=1");$s->execute(array_merge([$tenant['id']],$ids));$rows=[];foreach($s->fetchAll() as $p){$p['quantity']=max(1,min(20,(int)$cart[$p['id']]));$p['line_total']=$p['quantity']*(float)$p['price'];$rows[]=$p;}return $rows;}
function public_footer(array $tenant): void {echo '<footer class="mt-16 border-t border-stone-200 bg-stone-100"><div class="mx-auto grid max-w-7xl gap-8 px-4 py-12 sm:grid-cols-2 lg:grid-cols-4"><div><b>'.e($tenant['name']).'</b><p class="mt-3 text-sm text-stone-600">'.e($tenant['tagline']).'</p></div><div><b>Shop</b><a class="mt-3 block text-sm text-stone-600" href="'.tenant_url($tenant,'shop').'">All products</a><a class="mt-2 block text-sm text-stone-600" href="'.tenant_url($tenant,'search').'">Search catalog</a></div><div><b>Account</b><a class="mt-3 block text-sm text-stone-600" href="'.tenant_url($tenant,'account').'">Sign in</a><a class="mt-2 block text-sm text-stone-600" href="'.tenant_url($tenant,'tracking').'">Track order</a></div><div><b>Store owner?</b><a class="mt-3 block text-sm text-stone-600" href="/admin/login">Admin login</a></div></div></footer>';}

if($_SERVER['REQUEST_METHOD']==='POST') try {
    verify_csrf(); $action=$_POST['action']??'';
    if($action==='add_cart') { $pid=(int)$_POST['product_id'];$s=$db->prepare('SELECT id FROM products WHERE id=? AND tenant_id=? AND is_active=1');$s->execute([$pid,$tenant['id']]);if(!$s->fetch())throw new RuntimeException('This product is unavailable.');$_SESSION['cart'][$pid]=min(20,(int)($_SESSION['cart'][$pid]??0)+1);flash('Added to your bag.');redirect(tenant_url($tenant,'cart')); }
    if($action==='checkout') {
        $rows=cart_products($db,$tenant);if(!$rows)throw new RuntimeException('Your bag is empty.');$required=['name','email','phone','address','city','state','pincode'];foreach($required as $field)if(trim($_POST[$field]??'')==='')throw new RuntimeException('Complete all delivery details.');
        $subtotal=array_sum(array_column($rows,'line_total'));$number='ECM-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$db->beginTransaction();$s=$db->prepare('INSERT INTO orders (tenant_id,user_id,order_number,customer_name,customer_email,customer_phone,shipping_address,city,state,pincode,subtotal,total,payment_method) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$tenant['id'],current_user($db)['id']??null,$number,trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['address']),trim($_POST['city']),trim($_POST['state']),trim($_POST['pincode']),$subtotal,$subtotal,$_POST['payment_method']==='cod'?'cod':'prepaid']);$orderId=(int)$db->lastInsertId();$item=$db->prepare('INSERT INTO order_items (order_id,product_id,product_name,sku,unit_price,quantity) VALUES (?,?,?,?,?,?)');foreach($rows as $p)$item->execute([$orderId,$p['id'],$p['name'],$p['sku'],$p['price'],$p['quantity']]);$db->commit();$order=$db->prepare('SELECT * FROM orders WHERE id=?');$order->execute([$orderId]);$order=$order->fetch();$_SESSION['cart']=[];
        $hosted=fastrr_checkout_url($tenant,$order);if($hosted&&$order['payment_method']==='prepaid')redirect($hosted);try{$shipment=shiprocket_create_shipment($db,$tenant,$order);$db->prepare('UPDATE orders SET shiprocket_order_id=?,awb_code=? WHERE id=?')->execute([(string)($shipment['order_id']??''),(string)($shipment['shipment_id']??''),$orderId]);}catch(Throwable $ignored){}flash('Order '.$number.' created. We will keep you updated.');redirect(tenant_url($tenant,'order/'.$number));
    }
    if($action==='signup') { $name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';if(!$name||!$email||strlen($password)<8)throw new RuntimeException('Use your name, a valid email and an 8 character password.');$s=$db->prepare('INSERT INTO users (tenant_id,name,email,password_hash) VALUES (?,?,?,?)');$s->execute([$tenant['id'],$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$_SESSION['user_id']=$db->lastInsertId();flash('Your account has been created.');redirect(tenant_url($tenant,'account')); }
    if($action==='logout') { unset($_SESSION['user_id']);flash('You have been logged out.');redirect(tenant_url($tenant)); }
    if($action==='login') { $s=$db->prepare('SELECT * FROM users WHERE tenant_id=? AND email=?');$s->execute([$tenant['id'],strtolower(trim($_POST['email']??''))]);$user=$s->fetch();if(!$user||!password_verify($_POST['password']??'',$user['password_hash']))throw new RuntimeException('Incorrect email or password.');$_SESSION['user_id']=$user['id'];flash('Welcome back.');redirect(tenant_url($tenant,'account')); }
} catch(Throwable $e) { if($db->inTransaction())$db->rollBack();flash($e->getMessage(),'error');redirect(tenant_url($tenant,$path)); }

if($path===''){ $b=$db->prepare('SELECT * FROM banners WHERE tenant_id=? AND is_active=1 ORDER BY sort_order,id');$b->execute([$tenant['id']]);$banners=$b->fetchAll();$p=$db->prepare('SELECT * FROM products WHERE tenant_id=? AND is_active=1 ORDER BY id DESC LIMIT 8');$p->execute([$tenant['id']]);h_start($tenant);header_nav($db,$tenant);echo '<main><section class="relative overflow-hidden bg-[var(--soft)]" x-data="{i:0,n:'.max(1,count($banners)).'}">';if($banners){foreach($banners as $i=>$banner)echo '<article x-show="i=='.$i.'" class="relative min-h-[30rem]" '.($i?'style="display:none"':'').'>'.($banner['image_url']?'<img class="absolute inset-0 h-full w-full object-cover opacity-50 mix-blend-multiply" src="'.e($banner['image_url']).'" alt="">':'<div class="absolute inset-y-0 right-0 w-1/2 bg-gradient-to-br from-white/40 to-transparent"></div>').'<div class="relative mx-auto flex min-h-[30rem] max-w-7xl items-center px-4"><div class="max-w-2xl"><span class="text-xs font-bold tracking-[.2em]">FEATURED OFFER</span><h1 class="display mt-4 text-5xl leading-none sm:text-7xl">'.e($banner['title']).'</h1><p class="mt-5 max-w-lg text-base text-stone-700">'.e($banner['subtitle']).'</p><a class="mt-7 inline-flex rounded bg-zinc-900 px-5 py-3 text-sm font-bold text-white" href="'.e($banner['cta_url']).'">'.e($banner['cta_label']).' →</a></div></div></article>';if(count($banners)>1)echo '<div class="absolute bottom-5 left-1/2 flex -translate-x-1/2 gap-2">'.implode('',array_map(fn($i)=>'<button class="h-1 w-6 bg-zinc-800/40" @click="i='.$i.'"></button>',array_keys($banners))).'</div><script>setInterval(()=>{let e=document.querySelector("[x-data]");if(e&&e.__x)e.__x.$data.i=(e.__x.$data.i+1)%e.__x.$data.n},5000)</script>';}else echo '<div class="mx-auto grid min-h-[30rem] max-w-7xl grid-cols-1 items-center px-4 md:grid-cols-2"><div><span class="text-xs font-bold tracking-[.2em]">WELCOME TO '.e(strtoupper($tenant['name'])).'</span><h1 class="display mt-4 text-5xl leading-none sm:text-7xl">'.e($tenant['hero_title']?:$tenant['tagline']).'</h1><p class="mt-5 max-w-lg text-base text-stone-700">'.e($tenant['description']).'</p><a class="mt-7 inline-flex rounded bg-zinc-900 px-5 py-3 text-sm font-bold text-white" href="'.tenant_url($tenant,'shop').'">Explore collection →</a></div><div class="surface m-6 grid aspect-square place-items-center bg-white/40 text-sm text-stone-500">Upload a hero image in Admin</div></div>';echo '</section><section class="mx-auto max-w-7xl px-4 py-20"><div class="flex items-end justify-between"><div><span class="text-xs font-bold tracking-[.2em] text-stone-500">THE COLLECTION</span><h2 class="display mt-3 text-4xl sm:text-6xl">Built around<br><em class="text-[var(--accent)]">your products.</em></h2></div><a class="text-sm font-semibold underline" href="'.tenant_url($tenant,'shop').'">View all</a></div><div class="mt-12 grid grid-cols-2 gap-x-4 gap-y-9 md:grid-cols-4">';foreach($p->fetchAll() as $row)echo product_card($tenant,$row);echo '</div></section></main>';public_footer($tenant);h_end();exit;}

if($path==='shop'||$path==='search'){ $query=trim($_GET['q']??'');$category=trim($_GET['category']??'');$sql='SELECT DISTINCT p.* FROM products p LEFT JOIN product_categories pc ON pc.product_id=p.id LEFT JOIN categories c ON c.id=pc.category_id WHERE p.tenant_id=? AND p.is_active=1';$args=[$tenant['id']];if($query){$sql.=' AND (MATCH(p.name,p.description) AGAINST (? IN BOOLEAN MODE) OR p.name LIKE ? OR p.description LIKE ? OR c.name LIKE ?)';$boolean=implode(' ',array_map(fn($v)=>'+'.preg_replace('/[^\pL\pN]/u','',$v).'*',preg_split('/\s+/',$query)));$like='%'.$query.'%';$args=array_merge($args,[$boolean,$like,$like,$like]);}if($category){$sql.=' AND c.slug=?';$args[]=$category;}$sql.=' ORDER BY p.id DESC';$s=$db->prepare($sql);$s->execute($args);h_start($tenant,$query?'Search results · '.$tenant['name']:'Shop · '.$tenant['name']);header_nav($db,$tenant);echo '<main class="mx-auto min-h-[60vh] max-w-7xl px-4 py-16"><span class="text-xs font-bold tracking-[.2em] text-stone-500">'.($query?'CATALOG SEARCH':'THE COLLECTION').'</span><h1 class="display mt-3 text-5xl sm:text-7xl">'.($query?'Search <em class="text-[var(--accent)]">results.</em>':'Find your next<br><em class="text-[var(--accent)]">favourite.</em>').'</h1><form class="mt-8 flex max-w-xl overflow-hidden border border-stone-300 bg-white" method="get"><input type="hidden" name="store" value="'.e($tenant['slug']).'"><input class="min-w-0 flex-1 px-4 py-3 text-sm outline-none" name="q" value="'.e($query).'" placeholder="Search names, descriptions or categories"><button class="bg-zinc-900 px-5 text-sm font-bold text-white">Search</button></form><div class="mt-7 flex gap-4 overflow-auto border-b border-stone-200 whitespace-nowrap"> <a class="pb-3 text-sm '.(!$category?'border-b-2 border-[var(--accent)] font-bold':'text-stone-500').'" href="'.tenant_url($tenant,'shop').'">All</a>';foreach(categories($db,$tenant['id']) as $c)echo '<a class="pb-3 text-sm '.($category===$c['slug']?'border-b-2 border-[var(--accent)] font-bold':'text-stone-500').'" href="'.tenant_url($tenant,'shop',['category'=>$c['slug']]).'">'.e($c['name']).'</a>';echo '</div><div class="mt-10 grid grid-cols-2 gap-x-4 gap-y-9 md:grid-cols-4">';$rows=$s->fetchAll();if($rows)foreach($rows as $row)echo product_card($tenant,$row);else echo '<div class="col-span-full surface rounded-xl border border-dashed border-stone-300 p-12 text-center text-sm text-stone-500">No products matched. Search runs across product titles, descriptions, and every category attached to a product.</div>';echo '</div></main>';public_footer($tenant);h_end();exit;}

if(str_starts_with($path,'product/')){$slug=basename($path);$s=$db->prepare('SELECT * FROM products WHERE tenant_id=? AND slug=? AND is_active=1');$s->execute([$tenant['id'],$slug]);$p=$s->fetch();if(!$p){http_response_code(404);$path='404';}else{h_start($tenant,$p['name'].' · '.$tenant['name'],$p['description'],$p);header_nav($db,$tenant);echo '<main class="mx-auto grid max-w-6xl gap-10 px-4 py-14 md:grid-cols-2"><div class="surface aspect-square overflow-hidden bg-stone-200">'.($p['image_url']?'<img class="h-full w-full object-cover" src="'.e($p['image_url']).'" alt="'.e($p['name']).'">':'<span class="grid h-full place-items-center text-stone-500">Product image</span>').'</div><section class="self-center"><p class="text-xs font-bold tracking-[.15em] text-stone-500">'.e(implode(' · ',product_categories($db,$p['id']))).'</p><h1 class="display mt-4 text-5xl">'.e($p['name']).'</h1><p class="mt-4 text-xl font-semibold">'.money((float)$p['price']).'</p><p class="mt-6 whitespace-pre-line text-sm leading-7 text-stone-600">'.e($p['description']).'</p><p class="mt-6 text-xs text-stone-500">'.((int)$p['stock']>0?(int)$p['stock'].' in stock':'Availability on request').'</p><form method="post" action="'.tenant_url($tenant,'cart').'" class="mt-7">'.csrf_input().'<input type="hidden" name="action" value="add_cart"><input type="hidden" name="product_id" value="'.$p['id'].'"><button class="w-full rounded bg-zinc-900 px-5 py-3 text-sm font-bold text-white">Add to bag →</button></form></section></main>';public_footer($tenant);h_end();exit;}}

if($path==='cart'||$path==='checkout'){ $rows=cart_products($db,$tenant);$subtotal=array_sum(array_column($rows,'line_total'));h_start($tenant,$path==='cart'?'Your bag':'Checkout');header_nav($db,$tenant);echo '<main class="mx-auto max-w-6xl px-4 py-14"><h1 class="display text-5xl">'.($path==='cart'?'Your bag.':'Checkout.').'</h1>';if(!$rows){echo '<p class="mt-6 text-stone-600">Your bag is empty. <a class="underline" href="'.tenant_url($tenant,'shop').'">Explore products</a></p>';}elseif($path==='cart'){echo '<div class="mt-10 grid gap-10 md:grid-cols-[1fr_22rem]"><div>';foreach($rows as $p)echo '<article class="flex gap-4 border-t border-stone-200 py-4">'.($p['image_url']?'<img class="h-20 w-16 object-cover" src="'.e($p['image_url']).'" alt="">':'<span class="h-20 w-16 bg-stone-200"></span>').'<div class="flex-1"><b class="text-sm">'.e($p['name']).'</b><p class="mt-1 text-xs text-stone-500">'.money((float)$p['price']).' × '.$p['quantity'].'</p></div><b class="text-sm">'.money($p['line_total']).'</b></article>';echo '</div><aside class="surface h-max rounded-xl bg-stone-100 p-5"><div class="flex justify-between text-sm"><span>Subtotal</span><b>'.money($subtotal).'</b></div><a class="mt-6 block rounded bg-zinc-900 px-4 py-3 text-center text-sm font-bold text-white" href="'.tenant_url($tenant,'checkout').'">Continue to checkout →</a></aside></div>';}else echo '<form method="post" class="mt-10 grid gap-10 md:grid-cols-[1fr_22rem]">'.csrf_input().'<input type="hidden" name="action" value="checkout"><section class="surface rounded-xl border border-stone-200 bg-white p-5"><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm">Full name<input required class="mt-1 w-full border border-stone-300 p-3" name="name"></label><label class="text-sm">Email<input required type="email" class="mt-1 w-full border border-stone-300 p-3" name="email"></label><label class="text-sm">Phone<input required class="mt-1 w-full border border-stone-300 p-3" name="phone"></label><label class="text-sm">Pincode<input required class="mt-1 w-full border border-stone-300 p-3" name="pincode"></label><label class="text-sm sm:col-span-2">Address<textarea required class="mt-1 w-full border border-stone-300 p-3" name="address"></textarea></label><label class="text-sm">City<input required class="mt-1 w-full border border-stone-300 p-3" name="city"></label><label class="text-sm">State<input required class="mt-1 w-full border border-stone-300 p-3" name="state"></label><label class="text-sm">Payment<select class="mt-1 w-full border border-stone-300 p-3" name="payment_method"><option value="prepaid">Prepaid</option><option value="cod">Cash on delivery</option></select></label></div></section><aside class="surface h-max rounded-xl bg-stone-100 p-5"><p class="flex justify-between text-sm"><span>Subtotal</span><b>'.money($subtotal).'</b></p><button class="mt-6 w-full rounded bg-zinc-900 px-4 py-3 text-sm font-bold text-white">Continue securely →</button></aside></form>';echo '</main>';public_footer($tenant);h_end();exit;}

if($path==='about'){h_start($tenant,'About · '.$tenant['name']);header_nav($db,$tenant);echo '<main class="grid min-h-[60vh] grid-cols-1 bg-[var(--soft)] md:grid-cols-2"><section class="flex items-center px-6 py-20 md:px-24"><div><span class="text-xs font-bold tracking-[.2em]">OUR STORY</span><h1 class="display mt-4 text-5xl sm:text-7xl">'.e($tenant['name']).'<br><em class="text-[var(--accent)]">in your own words.</em></h1><p class="mt-6 max-w-xl whitespace-pre-line text-sm leading-7 text-stone-600">'.e($tenant['description']).'</p><a class="mt-8 inline-block rounded bg-zinc-900 px-5 py-3 text-sm font-bold text-white" href="'.tenant_url($tenant,'shop').'">Explore collection →</a></div></section><div class="grid min-h-80 place-items-center bg-[var(--brand)] text-6xl text-white">'.($tenant['logo_url']?'<img class="h-36 w-36 object-contain brightness-0 invert" src="'.e($tenant['logo_url']).'" alt="">':'✦').'</div></main>';public_footer($tenant);h_end();exit;}
